def source_key(section,field):
 require(all(ord(c)<128 for c in section+field),'Only checked ASCII source keys are supported')
 value=0
 for c in (section+'*'+field).lower():value=(ord(c)+65599*value)&0xffffffff
 return f'{value:08x}'

